/* =========================================================
   SafarPro demo — pages: finance, management, system
   ========================================================= */

/* ---------- Payments ---------- */
PAGES.payments = () => {
  const list = S.payments.filter(inB); const posted = list.filter(p => p.status === 'Posted');
  const by = m => sum(posted.filter(p => p.method === m), p => p.amount);
  const refunds = sum(S.refunds.filter(r => r.status === 'Completed'), r => r.approved);
  return `${ph('Payments & Receipts', 'Customer receipts, partial payments and controlled reversals.', btn('Receive Payment', 'receivePayment', { cls:'btn-p', icon:'hand-coins', perm:'payment.create' }))}
  <div class="grid g5">${kpi({ l:'Total collections', v:money(sum(posted, p => p.amount)), s:`${posted.length} receipts`, i:'hand-coins', t:'ok' })}${kpi({ l:'Cash received', v:money(by('Cash')), i:'banknote', t:'nv' })}${kpi({ l:'Bank received', v:money(by('Bank Transfer') + by('Card')), s:'Bank transfer & card', i:'landmark', t:'info' })}${kpi({ l:'Online / digital', v:money(by('Digital Payment')), i:'smartphone' })}${kpi({ l:'Refunds paid', v:money(refunds), i:'undo-2', t:'warn', r:'refunds' })}</div>
  <div class="mt">${card('', table('payments', { rows:list, select:true, perm:'payment', ph:'Search receipt, customer or reference…', search:p => `${p.ref} ${partyName(bk(p.bookingId))} ${p.txRef} ${bk(p.bookingId)?.ref || ''}`,
    filters:[{ k:'method', l:'Method', opts:METHODS, get:p => p.method }, { k:'status', l:'Status', opts:['Posted','Reversed'], get:p => p.status }, { k:'branch', l:'Branch', opts:brOpts(), get:p => p.branch }],
    open:p => `data-a="viewReceipt" data-id="${p.id}"`,
    cols:[{ h:'Receipt', v:p => p.ref, r:p => `<span class="mono t1">${p.ref}</span>` }, { h:'Date', v:p => p.date, r:p => fd(p.date) }, { h:'Customer', v:p => partyName(bk(p.bookingId)) }, { h:'Booking', v:p => bk(p.bookingId)?.ref || '', r:p => `<span class="mono">${bk(p.bookingId)?.ref || '—'}</span>` }, { h:'Method', v:p => p.method }, { h:'Amount', v:p => p.amount, al:'r', r:p => `<span class="${p.status === 'Reversed' ? 'mut3' : ''}" style="${p.status === 'Reversed' ? 'text-decoration:line-through' : ''}">${pk(p.amount)}</span>` }, { h:'Recorded by', v:p => empName(p.by) }, { h:'Status', v:p => p.status, r:p => pill(p.status) }, { h:'', exp:false, r:p => `<div class="rowact">${sbtn('', 'viewReceipt', { icon:'receipt', cls:'btn-g', data:`data-id="${p.id}" aria-label="View receipt"` })}${p.status === 'Posted' ? sbtn('', 'reversePayment', { icon:'undo-2', cls:'btn-g', data:`data-id="${p.id}" aria-label="Reverse receipt"`, perm:'payment.reverse' }) : ''}</div>` }],
    foot:r => `<td colspan="6">Posted total</td><td class="r">${pk(sum(r.filter(p => p.status === 'Posted'), p => p.amount))}</td><td colspan="3"></td>`,
    empty:empty('receipt', 'No payments recorded', 'Receive a payment against a booking to generate a receipt.', btn('Receive Payment', 'receivePayment', { cls:'btn-p' })) }), { np:true })}</div>
  <p class="mut3" style="font-size:12px;margin-top:12px">Completed receipts are never edited or deleted. Mistakes are corrected with a reversal that keeps the original on record.</p>`;
};

/* ---------- Expenses ---------- */
PAGES.expenses = () => {
  const list = S.expenses.filter(inB); const appr = list.filter(e => e.status === 'Approved'); const month = appr.filter(e => e.date.startsWith(TODAY.slice(0, 7)));
  const byCat = {}; month.forEach(e => byCat[e.cat] = (byCat[e.cat] || 0) + e.amount); const top = Object.entries(byCat).sort((a, b) => b[1] - a[1])[0];
  return `${ph('Expenses', `Operating expenses with approval for amounts above ${pk(S.settings.expenseLimit)}.`, btn('Record Expense', 'newExpense', { cls:'btn-p', icon:'plus', perm:'expense.create' }))}
  <div class="mini">${kpi({ l:'Total expenses (approved)', v:money(sum(appr, e => e.amount)), i:'wallet' })}${kpi({ l:'Pending approval', v:list.filter(e => e.status === 'Pending').length, s:pk(sum(list.filter(e => e.status === 'Pending'), e => e.amount)), i:'clock', t:'warn', r:'expenses', p:'expenses|status=Pending' })}${kpi({ l:'This month', v:money(sum(month, e => e.amount)), i:'calendar', t:'info' })}${kpi({ l:'Largest category this month', v:top ? esc(top[0]) : '—', s:top ? pk(top[1]) : '', i:'layers' })}</div>
  ${card('', table('expenses', { rows:list, perm:'expense', search:e => `${e.ref} ${e.desc} ${e.cat}`, filters:[{ k:'status', l:'Status', opts:['Approved','Pending','Rejected'], get:e => e.status }, { k:'cat', l:'Category', opts:Object.keys(EXP_CATS), get:e => e.cat }],
    cols:[{ h:'Reference', v:e => e.ref, r:e => `<span class="mono">${e.ref}</span>` }, { h:'Date', v:e => e.date, r:e => fd(e.date) }, { h:'Category', v:e => e.cat, r:e => `<span class="tag">${e.cat}</span>` }, { h:'Description', v:e => e.desc, cls:'wrap', r:e => `${esc(e.desc)}${e.attachment ? ` <a class="t2" href="/documents/${e.attachment}/file" target="_blank" rel="noopener">${ic('paperclip')} ${esc(e.attachmentName)}</a>` : ''}` }, { h:'Paid from', v:e => ACC[e.account]?.name, r:e => `${esc(e.method)}<div class="t2">${esc(ACC[e.account]?.name || e.account)}</div>` }, { h:'Branch', v:e => byId(S.branches, e.branch)?.code || '' }, { h:'Amount', v:e => e.amount, al:'r', r:e => pk(e.amount) }, { h:'Submitted by', v:e => empName(e.by) }, { h:'Approval', v:e => e.status, r:e => `${pill(e.status)}${e.approvedBy ? `<div class="t2">${esc(e.approvedBy)}</div>` : ''}` }, { h:'', exp:false, r:e => e.status === 'Pending' ? `<div class="rowact">${sbtn('Approve', 'approveExpense', { cls:'btn-p', data:`data-id="${e.id}"`, perm:'expense.approve' })}${sbtn('Reject', 'rejectExpense', { cls:'btn-d', data:`data-id="${e.id}"`, perm:'expense.approve' })}</div>` : '' }],
    foot:r => `<td colspan="6">Approved total</td><td class="r">${pk(sum(r.filter(e => e.status === 'Approved'), e => e.amount))}</td><td colspan="3"></td>` }), { np:true })}
  <p class="mut3" style="font-size:12px;margin-top:12px">Only approved expenses post to the ledger. Supplier costs tied to a booking are recorded on the booking as direct costs, so they are never counted twice.</p>`;
};

/* ---------- Accounting ---------- */
function stmtTable(sections, totalLabel, total) {
  return `<div class="tw"><table class="tbl">${sections.map(([title, rows, tl, tv]) => `<thead><tr><th colspan="2">${title}</th></tr></thead><tbody>${rows.map(r => `<tr><td style="padding-left:24px">${r.code ? `<span class="mono mut">${r.code}</span> ` : ''}${esc(r.name)}</td><td class="r">${r.amt < 0 ? `(${num(-r.amt)})` : num(r.amt)}</td></tr>`).join('')}${tl ? `<tr><td class="t1">${tl}</td><td class="r t1">${tv < 0 ? `(${num(-tv)})` : num(tv)}</td></tr>` : ''}</tbody>`).join('')}${totalLabel ? `<tfoot><tr><td>${totalLabel}</td><td class="r ${total < 0 ? 'neg' : ''}">${pk(total)}</td></tr></tfoot>` : ''}</table></div>`;
}
function plHtml(from, to) {
  const p = pl(from, to); const nz = r => r.amt !== 0;
  return stmtTable([['Revenue', p.inc.filter(nz), 'Total revenue', p.ti], ['Direct costs (cost of sales)', p.dc.filter(nz), 'Gross profit', p.gp], ['Operating expenses', p.op.filter(nz), 'Total operating expenses', p.top]], 'Net profit / (loss)', p.np) + `<p class="mut3" style="font-size:12px;padding:10px 16px">Accrual basis: revenue is recognised when a booking is confirmed, not when cash is received. Cancellation reversals reduce revenue. ${fd(from)} – ${fd(to)}.</p>`;
}
function bsHtml() {
  const ar = subledgerAR(); const A_ = CASH_ACCTS.map(c => ({ code:c, name:ACC[c].name, amt:natural(c) })).filter(r => r.amt);
  const assets = [...A_, { code:'1100', name:'Accounts receivable (customers & agents)', amt:ar.pos }, { code:'1200', name:'Supplier advances', amt:natural('1200') }].filter(r => r.amt);
  const liab = [{ code:'2000', name:'Accounts payable (suppliers)', amt:natural('2000') }, { code:'2100', name:'Customer advances & credits due', amt:ar.adv + natural('2100') }, { code:'2200', name:'Other liabilities', amt:natural('2200') }].filter(r => r.amt);
  const cur = pl('0000', '9999').np; const eq = [{ code:'3000', name:'Owner capital', amt:natural('3000') }, { code:'3100', name:'Retained earnings', amt:natural('3100') }, { name:'Current period earnings', amt:cur }].filter(r => r.amt);
  const ta = sum(assets, r => r.amt), tl = sum(liab, r => r.amt), te = sum(eq, r => r.amt); const ok = ta === tl + te;
  return `<div class="cb">${ok ? note(`<b>Balanced.</b> Total assets equal liabilities plus equity (${pk(ta)}).`, 'ok', 'scale') : note(`Out of balance by ${pk(ta - tl - te)}.`, 'err', 'circle-alert')}</div>${stmtTable([['Assets', assets, 'Total assets', ta], ['Liabilities', liab, 'Total liabilities', tl], ['Equity', eq, 'Total equity', te]], 'Total liabilities & equity', tl + te)}<p class="mut3" style="font-size:12px;padding:10px 16px">As at ${fd(TODAY)}. Customer balances are split: amounts owed to you are assets; payments received ahead of invoicing, and credits due after cancellations, are liabilities.</p>`;
}
function tbCard() { const rows = tbRows(); const td = sum(rows, r => r.net > 0 ? r.net : 0), tc = sum(rows, r => r.net < 0 ? -r.net : 0); return card('Trial balance', `<div class="cb">${td === tc ? note(`<b>Balanced.</b> Debits ${pk(td)} = credits ${pk(tc)}.`, 'ok', 'scale') : note(`Out of balance by ${pk(td - tc)}.`, 'err', 'circle-alert')}</div><div class="tw"><table class="tbl"><thead><tr><th>Code</th><th>Account</th><th>Type</th><th class="r">Debit</th><th class="r">Credit</th></tr></thead><tbody>${rows.map(r => `<tr><td class="mono">${r.code}</td><td>${esc(r.name)}</td><td><span class="tag">${r.type}</span></td><td class="r">${r.net > 0 ? num(r.net) : ''}</td><td class="r">${r.net < 0 ? num(-r.net) : ''}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="3">Totals</td><td class="r">${num(td)}</td><td class="r">${num(tc)}</td></tr></tfoot></table></div>`, { np:true, sub:`As at ${fd(TODAY)}`, right:sbtn('Export', 'tbExport', { icon:'download', perm:'journal.export' }) }); }
function tbRows(to = '9999') { return ACCOUNTS.map(a => { const b = acctBal(a.code, '0000', to); return { ...a, d:b.d, c:b.c, net:b.d - b.c }; }).filter(r => r.d || r.c); }
PAGES.accounting = () => {
  const tab = curTab('accounting', 'pl'); const J = getJ(); let body = '';
  const P = UI.plR || { from:TODAY.slice(0, 8) + '01', to:TODAY };
  if (tab === 'coa') body = card('', table('coa', { rows:ACCOUNTS.map(a => ({ ...a, id:a.code })), perm:'journal', noPage:true, filters:[{ k:'type', l:'Type', opts:['Asset','Liability','Equity','Income','Expense'], get:a => a.type }], cols:[{ h:'Code', v:a => a.code, r:a => `<span class="mono t1">${a.code}</span>` }, { h:'Account', v:a => a.name }, { h:'Type', v:a => a.type, r:a => `<span class="tag">${a.type}</span>` }, { h:'Group', v:a => a.group }, { h:'Balance', v:a => natural(a.code), al:'r', r:a => pk(natural(a.code)) }, { h:'', exp:false, r:a => sbtn('Ledger', 'glOpen', { cls:'btn-g', data:`data-v="${a.code}"` }) }] }), { np:true });
  if (tab === 'journal') { const rows = [...J].reverse().map(e => ({ ...e, dt:sum(e.lines, l => l[1]), ct:sum(e.lines, l => l[2]) })); body = card('', table('journal', { rows, perm:'journal', ps:15, ph:'Search reference or narration…', search:e => `${e.ref} ${e.memo}`, tools:btn('New journal entry', 'newJournal', { cls:'btn-p btn-sm', icon:'plus', perm:'journal.create' }), filters:[{ k:'src', l:'Source', opts:['Opening','Booking','Cost adjustment','Cancellation','Receipt','Reversal','Supplier payment','Expense','Refund','Commission','Cash closing','Transfer','Manual journal'], get:e => e.src }], open:e => `data-a="jeOpen" data-id="${e.id}"`, cols:[{ h:'Date', v:e => e.date, r:e => fd(e.date) }, { h:'Reference', v:e => e.ref, r:e => `<span class="mono">${e.ref}</span>` }, { h:'Narration', v:e => e.memo, cls:'wrap' }, { h:'Source', v:e => e.src, r:e => `<span class="tag">${e.src}</span>` }, { h:'Posted by', v:e => e.by }, { h:'Debit', v:e => e.dt, al:'r', r:e => num(e.dt) }, { h:'Credit', v:e => e.ct, al:'r', r:e => num(e.ct) }, { h:'Check', v:e => e.dt === e.ct ? 'Balanced' : 'Unbalanced', r:e => e.dt === e.ct ? `<span class="pos">${ic('check')}</span>` : pill('Unbalanced', 'err') }] }), { np:true, sub:'Generated automatically from bookings, receipts, payments, expenses and refunds — every entry balances.' }); }
  if (tab === 'gl') { const code = ACC[UI.gl] ? UI.gl : '1010'; let run = 0; const ent = J.filter(e => e.lines.some(l => l[0] === code)).map(e => { const d = sum(e.lines.filter(l => l[0] === code), l => l[1]), c = sum(e.lines.filter(l => l[0] === code), l => l[2]); const t = ACC[code].type; run += (t === 'Asset' || t === 'Expense') ? d - c : c - d; return { ...e, d, c, bal:run }; });
    body = card(`General ledger`, `<div class="tbar"><select class="inp" data-ch="glAcct" aria-label="Account" style="max-width:360px">${ACCOUNTS.map(a => `<option value="${a.code}" ${a.code === code ? 'selected' : ''}>${a.code} · ${esc(a.name)}</option>`).join('')}</select><span class="sp"></span><span class="mut" style="font-size:12.5px">${ent.length} entries · closing ${pk(run)}</span></div><div class="tw"><table class="tbl"><thead><tr><th>Date</th><th>Reference</th><th>Narration</th><th class="r">Debit</th><th class="r">Credit</th><th class="r">Balance</th></tr></thead><tbody>${ent.slice(-80).reverse().map(e => `<tr><td>${fd(e.date)}</td><td class="mono">${e.ref}</td><td>${esc(e.memo)}</td><td class="r">${e.d ? num(e.d) : ''}</td><td class="r">${e.c ? num(e.c) : ''}</td><td class="r">${num(e.bal)}</td></tr>`).join('') || '<tr><td colspan="6" class="mut">No entries.</td></tr>'}</tbody></table></div>`, { np:true }); }
  if (tab === 'tb') body = tbCard();
  if (tab === 'pl') body = card('Profit & loss', plHtml(P.from, P.to), { np:true, right:`<input type="date" class="inp" value="${P.from}" data-ch="plFrom" aria-label="From"><span class="mut">to</span><input type="date" class="inp" value="${P.to}" data-ch="plTo" aria-label="To">` });
  if (tab === 'bs') body = card('Balance sheet', bsHtml(), { np:true });
  if (tab === 'ar') { const ar = subledgerAR(); const bucket = b => { if (payStatus(b) !== 'Overdue') return 'Current'; const dd = ddiff(TODAY, dueOf(b)); return dd <= 30 ? '1–30 days' : dd <= 60 ? '31–60 days' : '60+ days'; }; const rows = ar.items.map(b => ({ ...b, bucket:bucket(b) }));
    body = `<div class="mini">${['Current','1–30 days','31–60 days','60+ days'].map(k => kpi({ l:k === 'Current' ? 'Not yet due' : k + ' overdue', v:money(sum(rows.filter(r => r.bucket === k), balOf)), i:k === 'Current' ? 'clock' : 'alarm-clock', t:k === 'Current' ? 'ok' : k === '1–30 days' ? 'warn' : 'err' })).join('')}</div>${card('Customer receivables', table('ar', { rows, perm:'payment', search:b => `${b.ref} ${partyName(b)}`, filters:[{ k:'bucket', l:'Age', opts:['Current','1–30 days','31–60 days','60+ days'], get:b => b.bucket }], open:b => `data-a="go" data-r="booking" data-id="${b.id}"`, cols:[{ h:'Customer', v:partyName, r:b => `<span class="t1">${esc(partyName(b))}</span>` }, { h:'Booking', v:b => b.ref, r:b => `<span class="mono">${b.ref}</span>` }, { h:'Invoiced', v:b => b.postedOn, r:b => fd(b.postedOn) }, { h:'Due', v:dueOf, r:b => fd(dueOf(b)) }, { h:'Age', v:b => b.bucket, r:b => pill(b.bucket, b.bucket === 'Current' ? 'ok' : b.bucket === '1–30 days' ? 'warn' : 'err') }, { h:'Balance', v:balOf, al:'r', r:b => pk(balOf(b)) }], foot:r => `<td colspan="5">Total customer receivables</td><td class="r">${pk(sum(r, balOf))}</td>` }), { np:true, sub:`Plus ${pk(ar.agentOpen)} sub-agent opening balances brought forward` })}`; }
  if (tab === 'ap') { const rows = S.suppliers.map(s => ({ ...s, l:supLedger(s) })).filter(s => s.l.balance); body = card('Accounts payable', table('ap', { rows, perm:'supplier', open:s => `data-a="go" data-r="supplier" data-id="${s.id}"`, cols:[{ h:'Supplier', v:s => s.name, r:s => `<span class="t1">${esc(s.name)}</span>` }, { h:'Terms', v:s => s.terms, r:s => s.terms + ' days' }, { h:'Invoiced', v:s => s.l.invT, al:'r', r:s => pk(s.l.invT) }, { h:'Paid', v:s => s.l.payT, al:'r', r:s => pk(s.l.payT) }, { h:'Overdue', v:s => s.l.overdue, al:'r', r:s => amt(s.l.overdue, { neg:true }) }, { h:'Balance', v:s => s.l.balance, al:'r', r:s => pk(s.l.balance) }], foot:r => `<td colspan="5">Total payables</td><td class="r">${pk(sum(r, s => s.l.balance))}</td>` }), { np:true }); }
  if (tab === 'cash' || tab === 'bank') { const codes = tab === 'cash' ? CASH_ACCTS.filter(c => ACC[c].group === 'Cash') : CASH_ACCTS.filter(c => ACC[c].group === 'Bank'); const code = codes.includes(UI.book) ? UI.book : codes[0]; let run = 0; const ent = J.filter(e => e.lines.some(l => l[0] === code)).map(e => { const d = sum(e.lines.filter(l => l[0] === code), l => l[1]), c = sum(e.lines.filter(l => l[0] === code), l => l[2]); run += d - c; return { ...e, d, c, bal:run }; });
    body = card(tab === 'cash' ? 'Cash book' : 'Bank book', `<div class="tbar"><div class="seg">${codes.map(c => `<button class="${c === code ? 'on' : ''}" data-a="book" data-v="${c}">${esc(ACC[c].name.replace('Cash in Hand — ', ''))}</button>`).join('')}</div><span class="sp"></span><b>${pk(run)}</b></div><div class="tw"><table class="tbl"><thead><tr><th>Date</th><th>Reference</th><th>Narration</th><th class="r">Receipts</th><th class="r">Payments</th><th class="r">Balance</th></tr></thead><tbody>${ent.slice(-60).reverse().map(e => `<tr><td>${fd(e.date)}</td><td class="mono">${e.ref}</td><td>${esc(e.memo)}</td><td class="r pos">${e.d ? num(e.d) : ''}</td><td class="r neg">${e.c ? num(e.c) : ''}</td><td class="r">${num(e.bal)}</td></tr>`).join('')}</tbody></table></div>`, { np:true }); }
  if (tab === 'periods') body = card('Financial periods', `<div class="tw"><table class="tbl"><thead><tr><th>Period</th><th>From</th><th>To</th><th>Status</th><th>Closed by</th><th></th></tr></thead><tbody>${S.periods.map(p => `<tr><td class="t1">${esc(p.name)}</td><td>${fd(p.from)}</td><td>${fd(p.to)}</td><td>${pill(p.status, p.status === 'Closed' ? '' : 'ok')}</td><td>${p.closedBy ? esc(p.closedBy) + ' · ' + fd(p.closedOn) : '—'}</td><td class="r">${p.status === 'Open' ? sbtn('Close period', 'closePeriod', { icon:'lock', data:`data-id="${p.id}"`, perm:'journal.approve' }) : ''}</td></tr>`).join('') || '<tr><td colspan="6" class="mut">No periods defined.</td></tr>'}</tbody></table></div><div class="cb">${note(closedUntil() > '0000' ? `Transactions dated on or before <b>${fd(closedUntil())}</b> are locked. Corrections go in an open period as new entries.` : 'No period is closed yet. Close a month after reconciling it to lock its transactions.', '', 'lock')}</div>`, { np:true, right:sbtn('New period', 'newPeriod', { icon:'plus', perm:'journal.approve' }) });
  return `${ph('Accounting', 'Double-entry books posted automatically from bookings, receipts, refunds, expenses and payments.', btn('Opening balances', 'newJournal', { icon:'scale', data:'data-opening="1"', perm:'journal.create' }) + btn('New journal entry', 'newJournal', { icon:'plus', perm:'journal.create' }))}
  ${note('Revenue is recognised when a booking is confirmed; supplier cost is booked at the same time. Sales tax (FBR / provincial) is not calculated — confirm your tax treatment with your accountant.', '', 'info')}
  <div class="mt">${tabs('accounting', [['pl', 'Profit & Loss'], ['bs', 'Balance Sheet'], ['tb', 'Trial Balance'], ['journal', 'Journal Entries', J.length], ['gl', 'General Ledger'], ['ar', 'Receivables'], ['ap', 'Payables'], ['cash', 'Cash Book'], ['bank', 'Bank Book'], ['coa', 'Chart of Accounts'], ['periods', 'Periods']], 'pl')}${body}</div>`;
};
CH.glAcct = v => { UI.gl = v; render(); };
A.glOpen = d => { UI.gl = d.v; UI.tabs.accounting = 'gl'; render(); };
A.book = d => { UI.book = d.v; render(); };
CH.plFrom = v => { UI.plR = { ...(UI.plR || { to:TODAY }), from:v }; render(); };
CH.plTo = v => { UI.plR = { ...(UI.plR || { from:'2026-10-01' }), to:v }; render(); };
A.jeOpen = d => { const e = byId(S.journal, d.id); if (!e) return; openDrawer(`Journal ${esc(e.ref)}`, `${kv([['Date', fd(e.date)], ['Narration', esc(e.memo)], ['Source', e.src], ['Posted by', esc(e.by)], ['Booking', e.booking && bk(e.booking) ? link(bk(e.booking).ref, 'booking', e.booking) : '—']])}<div class="tw mt"><table class="tbl"><thead><tr><th>Account</th><th class="r">Debit</th><th class="r">Credit</th></tr></thead><tbody>${e.lines.map(l => `<tr><td><span class="mono">${l[0]}</span> ${esc(ACC[l[0]].name)}</td><td class="r">${l[1] ? num(l[1]) : ''}</td><td class="r">${l[2] ? num(l[2]) : ''}</td></tr>`).join('')}</tbody><tfoot><tr><td>Totals</td><td class="r">${num(sum(e.lines, l => l[1]))}</td><td class="r">${num(sum(e.lines, l => l[2]))}</td></tr></tfoot></table></div>`); };
A.tbExport = () => { const rows = tbRows().map(r => ({ ...r, id:r.code })); downloadFile(`trial-balance-${TODAY}.csv`, csv([{ h:'Code', v:r => r.code }, { h:'Account', v:r => r.name }, { h:'Debit', v:r => r.net > 0 ? r.net : '' }, { h:'Credit', v:r => r.net < 0 ? -r.net : '' }], rows)); };

/* ---------- Refunds ---------- */
PAGES.refunds = () => {
  const list = S.refunds; const c = s => list.filter(r => r.status === s).length;
  return `${ph('Refunds', 'Every refund is linked to its original booking and payment, approved by role, and paid out once.', btn('Request Refund', 'newRefund', { cls:'btn-p', icon:'undo-2', perm:'refund.create' }))}
  <div class="mini">${kpi({ l:'Open requests', v:list.filter(r => !['Completed','Rejected'].includes(r.status)).length, s:pk(sum(list.filter(r => !['Completed','Rejected'].includes(r.status)), r => r.requested)) + ' requested', i:'inbox', t:'info' })}${kpi({ l:'Awaiting approval', v:c('Awaiting Approval'), i:'shield-question', t:'warn', r:'refunds', p:'refunds|status=Awaiting Approval' })}${kpi({ l:'Completed', v:c('Completed'), s:pk(sum(list.filter(r => r.status === 'Completed'), r => r.approved)) + ' paid out', i:'circle-check', t:'ok' })}${kpi({ l:'Rejected', v:c('Rejected'), i:'circle-x', t:'err' })}</div>
  ${card('', table('refunds', { rows:list, perm:'refund', search:r => `${r.ref} ${partyName(bk(r.bookingId))} ${bk(r.bookingId)?.ref || ''}`, filters:[{ k:'status', l:'Status', opts:[...REFUND_STAGES, 'Rejected'], get:r => r.status }], open:r => `data-a="openRefund" data-id="${r.id}"`,
    empty:empty('undo-2', 'No refunds', 'Refund requests appear here with their approval stage.'), cols:[{ h:'Refund', v:r => r.ref, r:r => `<span class="mono t1">${r.ref}</span>` }, { h:'Original booking', v:r => bk(r.bookingId)?.ref || '', r:r => `<span class="mono">${bk(r.bookingId)?.ref || '—'}</span>` }, { h:'Original payment', v:r => byId(S.payments, r.paymentId)?.ref || '', r:r => `<span class="mono">${byId(S.payments, r.paymentId)?.ref || '—'}</span>` }, { h:'Customer', v:r => partyName(bk(r.bookingId)) }, { h:'Requested', v:r => r.requested, al:'r', r:r => pk(r.requested) }, { h:'Approved', v:r => r.approved ?? '', al:'r', r:r => r.approved != null ? pk(r.approved) : '—' }, { h:'Fee', v:r => r.fee, al:'r', r:r => r.fee ? pk(r.fee) : '—' }, { h:'Method', v:r => r.method }, { h:'Requested by', v:r => r.reqBy }, { h:'Status', v:r => r.status, r:r => pill(r.status) }, { h:'', exp:false, r:r => `<div class="rowact">${refundActions(r).replace(/btn-sm/g, 'btn-sm')}</div>` }] }), { np:true })}
  <p class="mut3" style="font-size:12px;margin-top:12px">Approval above ${pk(S.settings.refundApprovalLimit)} requires an Administrator. “Mark paid” checks the refund’s status first, so repeated clicks never create a second payout.</p>`;
};

/* ---------- Commissions ---------- */
PAGES.commissions = () => {
  const tab = curTab('commissions', 'records'); const list = S.commissions;
  const t = (k, s) => sum(list.filter(c => c.kind === k && (!s || c.status === s)), c => c.amount);
  let body;
  if (tab === 'records') body = card('', table('comm', { rows:list, perm:'commission', search:c => `${c.ref} ${c.party} ${bk(c.bookingId)?.ref}`, filters:[{ k:'kind', l:'Type', opts:['Employee incentive','Sub-agent commission','Supplier commission (earned)'], get:c => c.kind }, { k:'status', l:'Status', opts:['Pending','Approved','Paid','Reversed','Netted in cost'], get:c => c.status }],
    cols:[{ h:'Reference', v:c => c.ref, r:c => `<span class="mono">${c.ref}</span>` }, { h:'Type', v:c => c.kind, r:c => `<span class="tag">${c.kind}</span>` }, { h:'Party', v:c => c.party, r:c => `<span class="t1">${esc(c.party)}</span>` }, { h:'Booking', v:c => bk(c.bookingId)?.ref || '', r:c => bk(c.bookingId) ? link(bk(c.bookingId).ref, 'booking', c.bookingId) : '—' }, { h:'Basis', v:c => c.basis, cls:'wrap' }, { h:'Amount', v:c => c.amount, al:'r', r:c => `<span class="${c.kind.includes('earned') ? 'pos' : ''}">${c.kind.includes('earned') ? '+' : ''}${pk(c.amount)}</span>` }, { h:'Date', v:c => c.date, r:c => fd(c.date) }, { h:'Status', v:c => c.status, r:c => pill(c.status) }, { h:'', exp:false, r:c => c.kind.includes('earned') ? '' : `<div class="rowact">${c.status === 'Pending' ? sbtn('Approve', 'commApprove', { data:`data-id="${c.id}"`, perm:'commission.approve' }) : ''}${c.status === 'Approved' ? sbtn('Pay', 'commPay', { cls:'btn-p', data:`data-id="${c.id}"`, perm:'commission.approve' }) : ''}${['Pending','Approved'].includes(c.status) ? sbtn('', 'commReverse', { icon:'undo-2', cls:'btn-g', data:`data-id="${c.id}" aria-label="Reverse"`, perm:'commission.reverse' }) : ''}</div>` }] }), { np:true });
  if (tab === 'rules') body = card('Commission rules', `<div class="tw"><table class="tbl"><thead><tr><th>Type</th><th>Service</th><th>Basis</th><th class="r">Rate</th><th></th></tr></thead><tbody>${S.commRules.map(r => `<tr><td><span class="tag">${r.kind}</span></td><td>${r.service}</td><td>${r.basis}</td><td class="r">${r.rate == null ? '—' : r.basis.startsWith('%') ? r.rate + '%' : pk(r.rate)}</td><td class="r">${r.rate != null ? sbtn('Edit', 'editRule', { icon:'pencil', cls:'btn-g', data:`data-id="${r.id}"`, perm:'settings.edit' }) : ''}</td></tr>`).join('')}</tbody></table></div>`, { np:true, sub:'Rules are set per service and party type. Changes apply to new bookings only.' });
  if (tab === 'statements') { const parties = [...new Set(list.filter(c => !c.kind.includes('earned')).map(c => c.party))]; body = card('Statements by party', `<div class="tw"><table class="tbl"><thead><tr><th>Party</th><th>Type</th><th class="r">Pending</th><th class="r">Approved</th><th class="r">Paid</th><th class="r">Reversed</th></tr></thead><tbody>${parties.map(p => { const cs = list.filter(c => c.party === p); const s = st => sum(cs.filter(c => c.status === st), c => c.amount); return `<tr><td class="t1">${esc(p)}</td><td>${cs[0].kind}</td><td class="r">${num(s('Pending'))}</td><td class="r">${num(s('Approved'))}</td><td class="r">${num(s('Paid'))}</td><td class="r mut">${num(s('Reversed'))}</td></tr>`; }).join('')}</tbody></table></div>`, { np:true }); }
  return `${ph('Commissions', 'Employee incentives, sub-agent commissions payable, and commission earned from suppliers.', '')}
  <div class="mini">${kpi({ l:'Employee incentives pending', v:money(t('Employee incentive', 'Pending') + t('Employee incentive', 'Approved')), s:'Payable to your staff', i:'user-round', t:'warn' })}${kpi({ l:'Sub-agent commission payable', v:money(t('Sub-agent commission', 'Pending') + t('Sub-agent commission', 'Approved')), s:'Owed to agents', i:'handshake', t:'info' })}${kpi({ l:'Paid this period', v:money(sum(list.filter(c => c.status === 'Paid'), c => c.amount)), i:'circle-check', t:'ok' })}${kpi({ l:'Earned from suppliers', v:money(t('Supplier commission (earned)')), s:'Income — netted in ticket cost', i:'trending-up', t:'nv' })}</div>
  ${tabs('commissions', [['records', 'Commission records', list.length], ['rules', 'Rules', S.commRules.length], ['statements', 'Statements']], 'records')}${body}`;
};

/* ---------- Cash & bank ---------- */
PAGES.cashbank = () => {
  const tab = curTab('cashbank', 'accounts'); const last = acct => S.closings.filter(c => c.account === acct).sort((a, b) => a.date < b.date ? 1 : -1)[0];
  let body = '';
  if (tab === 'accounts') body = `<div class="grid g3">${CASH_ACCTS.map(a => { const l = last(a); const bank = ACC[a].group === 'Bank'; const rec = bank ? (S.bankRecon.statement != null && a === '1010' ? (S.bankRecon.statement === natural('1010') ? 'Reconciled' : 'Unreconciled') : 'Not reconciled') : l ? (l.status.startsWith('Discrepancy') ? 'Discrepancy — pending review' : 'Balanced') : 'Not reconciled'; const br = S.branches.find(b => b.cashAccount === a); return `<section class="card"><div class="cb"><div style="display:flex;gap:10px;align-items:center"><span class="kpi-i ${bank ? 'info' : 'nv'}">${ic(bank ? 'landmark' : 'banknote')}</span><div><b style="font-size:13.5px">${esc(ACC[a].name)}</b><div class="mut" style="font-size:12px"><span class="mono">${a}</span> · ${bank ? 'Bank' : 'Cash'}${br ? ' · ' + esc(br.code) : ''}</div></div></div><div class="kpi-v" style="margin-top:12px">${money(natural(a))}</div><div style="display:flex;justify-content:flex-end;font-size:12px;margin-top:8px">${pill(rec)}</div><div class="mut3" style="font-size:11.5px;margin-top:6px">Last ${bank ? 'reconciliation' : 'closing'}: ${!bank && l ? fd(l.date) : '—'}</div></div></section>`; }).join('')}</div>`;
  if (tab === 'closing') body = `${card('Daily closing', table('closings', { rows:S.closings, perm:'cash', exp:false, tools:btn('Close today', 'dailyClose', { cls:'btn-p btn-sm', icon:'calculator', perm:'cash.create' }), cols:[{ h:'Reference', v:c => c.ref, r:c => `<span class="mono">${c.ref}</span>` }, { h:'Date', v:c => c.date, r:c => fd(c.date) }, { h:'Account', v:c => ACC[c.account]?.name }, { h:'Opening', v:c => c.opening, al:'r', r:c => num(c.opening) }, { h:'Receipts', v:c => c.receipts, al:'r', r:c => num(c.receipts) }, { h:'Payments', v:c => c.payments, al:'r', r:c => num(c.payments) }, { h:'Expected', v:c => c.expected, al:'r', r:c => num(c.expected) }, { h:'Counted', v:c => c.counted, al:'r', r:c => num(c.counted) }, { h:'Difference', v:c => c.diff, al:'r', r:c => c.diff ? `<b class="neg">${pk(c.diff)}</b>` : '<span class="pos">0</span>' }, { h:'Status', v:c => c.status, r:c => `${pill(c.status.startsWith('Adjusted') ? 'Balanced' : c.status)}${c.note ? `<div class="t2" style="white-space:normal;max-width:220px">${esc(c.note)}</div>` : ''}` }, { h:'', exp:false, r:c => c.status.startsWith('Discrepancy') ? sbtn('Approve adjustment', 'approveAdj', { data:`data-id="${c.id}"`, perm:'cash.approve' }) : c.adjPosted ? '<span class="t2">Adjustment posted</span>' : '' }], empty:empty('calculator', 'No closings yet', 'Count your cash at the end of each day and record it here.', btn('Close today', 'dailyClose', { cls:'btn-p', icon:'calculator' })) }), { np:true, sub:'Expected closing = opening + cash receipts − cash payments − cash refunds paid' })}<div class="mt">${note('The book balance is never changed to match a physical count. A difference stays visible until a manager approves a documented adjustment to “Cash Over / Short”.', '', 'shield-check')}</div>`;
  if (tab === 'recon') { const J = getJ().filter(e => e.lines.some(l => l[0] === '1010')).slice(-150); const book = natural('1010'); const unmatched = J.filter(e => !S.bankRecon.matched[e.id]); const stmt = S.bankRecon.statement; const um = sum(unmatched, e => sum(e.lines.filter(l => l[0] === '1010'), l => l[1] - l[2]));
    body = `<div class="grid g3">${card('', `<small class="mut">Book balance (1010)</small><div class="kpi-v">${money(book)}</div>`)}${card('', `<label class="mut" for="stmt-bal" style="font-size:12.5px">Bank statement balance</label><div class="money" style="margin-top:6px"><span>PKR</span><input id="stmt-bal" class="inp" type="number" step="1" value="${stmt ?? ''}" data-ch="recStmt" placeholder="From your bank statement" ${can('cash.edit') ? '' : 'disabled'}></div>`)}${card('', `<small class="mut">Difference</small><div class="kpi-v ${stmt != null && stmt !== book ? 'neg' : ''}">${stmt == null ? '—' : money(stmt - book)}</div><small class="mut">Unticked items total: ${pk(um)}</small>`)}</div>
    <div class="mt">${card('Bank entries — tick each one that appears on the bank statement', J.length ? `<div class="tw"><table class="tbl"><thead><tr><th class="cbx">Match</th><th>Date</th><th>Reference</th><th>Narration</th><th class="r">In</th><th class="r">Out</th></tr></thead><tbody>${[...J].reverse().map(e => { const d = sum(e.lines.filter(l => l[0] === '1010'), l => l[1]), c = sum(e.lines.filter(l => l[0] === '1010'), l => l[2]); return `<tr><td class="cbx"><input type="checkbox" aria-label="Matched" data-ch="recMatch" data-k="${e.id}" ${S.bankRecon.matched[e.id] ? 'checked' : ''} ${can('cash.edit') ? '' : 'disabled'}></td><td>${fd(e.date)}</td><td class="mono">${esc(e.ref)}</td><td>${esc(e.memo)}</td><td class="r pos">${d ? num(d) : ''}</td><td class="r neg">${c ? num(c) : ''}</td></tr>`; }).join('')}</tbody></table></div>` : empty('landmark', 'No bank entries yet', ''), { np:true })}</div>`; }
  if (tab === 'transfers') { const tr = S.journal.filter(j => j.src === 'Transfer'); body = card('Internal transfers', tr.length ? `<div class="tw"><table class="tbl"><thead><tr><th>Reference</th><th>Date</th><th>From</th><th>To</th><th class="r">Amount</th><th>Narration</th></tr></thead><tbody>${[...tr].reverse().map(j => { const to = j.lines.find(l => l[1] > 0), fr = j.lines.find(l => l[2] > 0); return `<tr><td class="mono">${esc(j.ref)}</td><td>${fd(j.date)}</td><td>${esc(ACC[fr[0]].name)}</td><td>${esc(ACC[to[0]].name)}</td><td class="r">${pk(to[1])}</td><td>${esc(j.memo)}</td></tr>`; }).join('')}</tbody></table></div>` : empty('arrow-left-right', 'No transfers yet', 'Record cash deposited to the bank or moved between branches.', btn('New transfer', 'transfer', { cls:'btn-p', icon:'plus', perm:'journal.create' })), { np:true, right:sbtn('New transfer', 'transfer', { icon:'plus', perm:'journal.create' }) }); }
  return `${ph('Cash & Bank', 'Branch cash, bank accounts, daily closing and reconciliation.', btn('Internal transfer', 'transfer', { icon:'arrow-left-right', perm:'journal.create' }) + btn('Daily closing', 'dailyClose', { cls:'btn-p', icon:'calculator', perm:'cash.create' }))}
  ${tabs('cashbank', [['accounts', 'Accounts', CASH_ACCTS.length], ['closing', 'Daily closing', S.closings.filter(c => c.status.startsWith('Discrepancy')).length || null], ['recon', 'Bank reconciliation'], ['transfers', 'Transfers']], 'accounts')}${body}`;
};

/* ---------- Employees & roles ---------- */
PAGES.employees = () => {
  const tab = curTab('employees', 'list'); let body;
  if (tab === 'list') body = card('', table('employees', { rows:S.employees.filter(inB), perm:'settings', search:e => `${e.name} ${e.code} ${e.role} ${e.username || ''}`, tools:btn('Add employee', 'newEmployee', { cls:'btn-p btn-sm', icon:'user-plus', perm:'settings.create' }), filters:[{ k:'role', l:'Role', opts:ROLES, get:e => e.role }, { k:'branch', l:'Branch', opts:brOpts(), get:e => e.branch }],
    cols:[{ h:'Name', v:e => e.name, r:e => `<div style="display:flex;gap:10px;align-items:center"><span class="av" style="width:30px;height:30px;font-size:11px">${initials(e.name)}</span><div><div class="t1">${esc(e.name)}${e.id === S.me.id ? ' <span class="tag">You</span>' : ''}</div><div class="t2">${esc(e.email || '')}</div></div></div>` }, { h:'Employee ID', v:e => e.code, r:e => `<span class="mono">${e.code}</span>` }, { h:'Role', v:e => e.role }, { h:'Branch', v:e => brName(e.branch) }, { h:'Login', v:e => e.username || '', r:e => e.hasLogin ? `<span class="mono">${esc(e.username)}</span>` : '<span class="mut3">No login</span>' }, { h:'Status', v:e => e.status, r:e => pill(e.status) }, { h:'Last sign-in', v:e => e.lastLogin || '', r:e => fdt(e.lastLogin) }, { h:'', exp:false, r:e => `<div class="rowact">${sbtn(e.hasLogin ? 'Reset password' : 'Create login', 'empLogin', { cls:'btn-g', icon:'key-round', data:`data-id="${e.id}"`, perm:'settings.edit' })}${sbtn('Role', 'empRole', { cls:'btn-g', icon:'shield', data:`data-id="${e.id}"`, perm:'settings.edit' })}${e.id !== S.me.id ? sbtn('', 'empStatus', { cls:'btn-g', icon:'power', data:`data-id="${e.id}" aria-label="Suspend or reactivate"`, perm:'settings.edit' }) : ''}</div>` }] }), { np:true });
  if (tab === 'perms') { const roles = ROLES; const L = { view:'V', create:'C', edit:'E', approve:'A', reverse:'R', export:'X', delete:'D' };
    body = card('Permissions matrix', `<div class="cb" style="border-bottom:1px solid var(--bd)"><div class="legend">${Object.entries(L).map(([k, v]) => `<span><b class="mono">${v}</b> ${k[0].toUpperCase() + k.slice(1)}</span>`).join('')}</div></div><div class="tw"><table class="tbl matrix"><thead><tr><th>Area</th>${roles.map(r => `<th class="c" style="white-space:normal;min-width:90px">${r}</th>`).join('')}</tr></thead><tbody>${S.permAreas.map(([a, l]) => `<tr><td class="t1">${l}</td>${roles.map(r => `<td class="c mono" style="font-size:11px;letter-spacing:.06em">${S.permActs.map(x => (S.roles[r] || []).includes(a + '.' + x) ? `<span class="yes">${L[x]}</span>` : `<span class="no">·</span>`).join('')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="cb">${note('These permissions are enforced by the SafarPro server on every request, not just by hiding buttons. Role changes take effect immediately.', '', 'shield-check')}</div>`, { np:true }); }
  return `${ph('Employees & Roles', 'Staff accounts, logins, branch assignment and what each role can do.', '')}${tabs('employees', [['list', 'Employees', S.employees.length], ['perms', 'Roles & permissions']], 'list')}${body}`;
};

/* ---------- Branches ---------- */
PAGES.branches = () => {
  const m = rangeOf('month');
  const st = br => { const bks = S.bookings.filter(b => b.branch === br.id && b.postedOn && b.postedOn >= m.from); return { sales:sum(bks, b => b.charged), ar:sum(S.bookings.filter(b => b.branch === br.id), b => Math.max(0, balOf(b))), emp:S.employees.filter(e => e.branch === br.id).length, cash:natural(BR_CASH[br.id]) }; };
  return `${ph('Branches', 'Performance and cash position for each office. Use the branch selector to filter the whole app.', btn('New branch', 'newBranch', { cls:'btn-p', icon:'plus', perm:'settings.create' }))}
  <div class="grid g3">${S.branches.map(b => { const s = st(b); return `<section class="card"><div class="ch"><span class="kpi-i nv">${ic('store')}</span><div><h3>${esc(b.name)}</h3><p><span class="mono">${b.code}</span> · ${esc(b.city)}</p></div><div class="r">${pill(b.status)}</div></div><div class="cb">${kv([['Address', esc(b.address)], ['Manager', b.manager ? empName(b.manager) : '—'], ['Phone', esc(b.phone)], ['Employees', s.emp], ['Cash in hand', pk(s.cash)], ['Sales this month', pk(s.sales)], ['Outstanding receivables', `<span class="${s.ar ? 'neg' : ''}">${pk(s.ar)}</span>`]])}<div class="mt" style="display:flex;gap:8px;flex-wrap:wrap">${sbtn('Branch dashboard', 'branchDash', { cls:'btn-p', icon:'layout-dashboard', data:`data-v="${b.id}"` })}${sbtn('Branch report', 'branchRep', { icon:'activity', data:`data-v="${b.id}"` })}</div></div></section>`; }).join('')}</div>
  <div class="mt">${card('Comparison · this month', `<div class="tw"><table class="tbl"><thead><tr><th>Branch</th><th class="r">Sales</th><th class="r">Collections</th><th class="r">Gross profit</th><th class="r">Expenses</th><th class="r">Receivables</th><th class="r">Cash</th></tr></thead><tbody>${S.branches.map(b => { const bks = S.bookings.filter(x => x.branch === b.id && x.postedOn && x.postedOn >= m.from); const coll = sum(S.payments.filter(p => p.branch === b.id && p.status === 'Posted' && p.date >= m.from), p => p.amount); const exp = sum(S.expenses.filter(e => e.branch === b.id && e.status === 'Approved' && e.date >= m.from), e => e.amount); const s = st(b); return `<tr><td class="t1">${esc(b.name)}</td><td class="r">${num(s.sales)}</td><td class="r">${num(coll)}</td><td class="r">${num(s.sales - sum(bks, x => x.cost - (x.cancel ? x.cancel.supplierCredit : 0)))}</td><td class="r">${num(exp)}</td><td class="r">${num(s.ar)}</td><td class="r">${num(s.cash)}</td></tr>`; }).join('')}</tbody></table></div>`, { np:true })}</div>`;
};
A.branchDash = d => { UI.branch = d.v; go('dashboard'); };
A.branchRep = d => { UI.branch = d.v; UI.rep = 'branch'; go('reports'); };

/* ---------- Sub-agents ---------- */
PAGES.subagents = () => {
  const tab = curTab('subagents', 'agents'); const list = S.agents; const reqs = S.agentReqs;
  let body;
  if (tab === 'agents') body = card('', table('agents', { rows:list, perm:'agent', search:a => `${a.name} ${a.city} ${a.code}`, tools:btn('Register agent', 'newAgent', { cls:'btn-p btn-sm', icon:'plus', perm:'agent.create' }), filters:[{ k:'status', l:'Status', opts:['Active','Pending approval','Suspended'], get:a => a.status }], open:a => `data-a="go" data-r="subagent" data-id="${a.id}"`,
    cols:[{ h:'Agent', v:a => a.name, r:a => `<div class="t1">${esc(a.name)}</div><div class="t2">${esc(a.city)} · <span class="mono">${a.code}</span></div>` }, { h:'Credit limit', v:a => a.limit, al:'r', r:a => pk(a.limit) }, { h:'Outstanding', v:agentBal, al:'r', r:a => amt(agentBal(a), { neg:true }) }, { h:'Credit used', v:a => a.limit ? agentBal(a) / a.limit : 0, r:a => { const p = a.limit ? agentBal(a) / a.limit * 100 : 0; return `<div class="cap">${bar(p, p > 85 ? 'e' : p > 60 ? 'w' : '')}<span style="width:36px;text-align:right">${p.toFixed(0)}%</span></div>`; } }, { h:'Wallet', v:a => a.wallet, al:'r', r:a => pk(a.wallet) }, { h:'Bookings', v:a => S.bookings.filter(b => b.agentId === a.id).length, al:'r' }, { h:'Commission', v:a => a.rate, r:a => a.rate + '%' }, { h:'Status', v:a => a.status, r:a => pill(a.status) }, { h:'', exp:false, r:a => a.status === 'Pending approval' ? sbtn('Approve', 'agentApprove', { cls:'btn-p', data:`data-id="${a.id}"`, perm:'agent.approve' }) : '' }], empty:empty('handshake', 'No sub-agents yet', 'Register partner agencies that book through you on credit.') }), { np:true });
  if (tab === 'requests') body = card('Booking requests from the agent portal', reqs.length ? `<div class="tw"><table class="tbl"><thead><tr><th>Agent</th><th>Service</th><th>Request</th><th class="r">Amount</th><th>Credit check</th><th>Received</th><th>Status</th><th></th></tr></thead><tbody>${reqs.map(q => { const a = agentOf(q.agentId); const after = agentBal(a) + q.amount; const ok = after <= a.limit; return `<tr><td class="t1">${esc(a.name)}</td><td>${q.service}</td><td class="wrap">${esc(q.desc)}</td><td class="r">${pk(q.amount)}</td><td>${q.status === 'Pending' ? (ok ? pill('Within limit', 'ok') : pill('Over limit')) + `<div class="t2">${pk(after)} of ${pk(a.limit)}</div>` : '—'}</td><td>${fd(q.date)}</td><td>${pill(q.status)}${q.bookingId && bk(q.bookingId) ? `<div class="t2">${link(bk(q.bookingId).ref, 'booking', q.bookingId)}</div>` : ''}${q.reason ? `<div class="t2">${esc(q.reason)}</div>` : ''}</td><td class="r">${q.status === 'Pending' ? `<div class="rowact">${sbtn('Approve', 'agentReq', { cls:'btn-p', data:`data-id="${q.id}" data-v="approve"`, perm:'agent.approve' })}${sbtn('Reject', 'agentReq', { cls:'btn-d', data:`data-id="${q.id}" data-v="reject"`, perm:'agent.approve' })}</div>` : ''}</td></tr>`; }).join('')}</tbody></table></div>` : empty('inbox', 'No requests', 'Log requests agents send you by phone or WhatsApp; approving runs a credit check.', btn('Log booking request', 'newAgentReq', { cls:'btn-p', icon:'plus', perm:'agent.create' })), { np:true, sub:'Approving runs a credit-limit check before the booking is created.' });
  return `${ph('Sub-Agents', 'Partner agencies that book through you on credit, with limits and approvals.', btn('Log booking request', 'newAgentReq', { icon:'inbox', perm:'agent.create' }) + btn('Register agent', 'newAgent', { cls:'btn-p', icon:'plus', perm:'agent.create' }))}
  <div class="mini">${kpi({ l:'Total agents', v:list.length, i:'handshake' })}${kpi({ l:'Active agents', v:list.filter(a => a.status === 'Active').length, i:'user-check', t:'ok' })}${kpi({ l:'Outstanding agent balances', v:money(sum(list, agentBal)), i:'file-clock', t:'warn' })}${kpi({ l:'Pending requests', v:reqs.filter(q => q.status === 'Pending').length + list.filter(a => a.status === 'Pending approval').length, s:'Bookings + registrations', i:'inbox', t:'info', r:'subagents', tab:'requests' })}</div>
  ${tabs('subagents', [['agents', 'Agents', list.length], ['requests', 'Booking requests', reqs.filter(q => q.status === 'Pending').length]], 'agents')}${body}`;
};
PAGES.subagent = ({ id }) => {
  const a = agentOf(id); if (!a) return card('', empty('handshake', 'Agent not found', '', btn('Back', 'go', { data:'data-r="subagents"' })));
  const bks = S.bookings.filter(b => b.agentId === id); const pays = S.payments.filter(p => p.agentId === id); const com = S.commissions.filter(c => c.partyId === id); const tab = curTab('subagent', 'overview'); const bal = agentBal(a);
  let body;
  if (tab === 'overview') body = `<div class="grid g2">${card('Agent profile', kv([['Agency', esc(a.name)], ['City', esc(a.city)], ['Contact', esc(a.contact)], ['Agent ID', `<span class="mono">${a.code}</span>`], ['Joined', fd(a.joined)], ['Commission', a.rate + '% (see Commission rules)'], ['Status', pill(a.status)]]))}${card('Credit position', calcBox([['Credit limit', pk(a.limit)], ['Outstanding', pk(bal), bal ? 'neg' : ''], ['Available credit', pk(Math.max(0, a.limit - bal)), 'pos'], ['Wallet balance', pk(a.wallet)]]) + `<div style="margin-top:12px">${bar(a.limit ? bal / a.limit * 100 : 0, a.limit && bal / a.limit > .85 ? 'e' : '')}</div><div class="mt" style="display:flex;gap:8px;flex-wrap:wrap">${sbtn('Change limit', 'agentLimit', { icon:'gauge', data:`data-id="${id}"`, perm:'agent.approve' })}${sbtn('Record payment', 'agentDeposit', { icon:'hand-coins', data:`data-id="${id}"`, perm:'payment.create' })}</div>`)}</div>`;
  if (tab === 'bookings') body = card('', table('ag-bk', { rows:bks, exp:false, open:b => `data-a="go" data-r="booking" data-id="${b.id}"`, cols:[{ h:'Booking', v:b => b.ref, r:b => `<span class="mono">${b.ref}</span>` }, { h:'Service', v:b => b.service }, { h:'Destination', v:b => b.destination }, { h:'Travel', v:b => b.travelDate, r:b => fd(b.travelDate) }, { h:'Amount', v:b => b.price, al:'r', r:b => pk(b.price) }, { h:'Balance', v:balOf, al:'r', r:b => amt(balOf(b), { neg:true }) }, { h:'Status', v:b => b.status, r:b => pill(b.status) }], empty:empty('calendar-x', 'No bookings', 'Approved agent requests appear here.') }), { np:true });
  if (tab === 'transactions' || tab === 'statements') { let run = a.opening; const rows = [{ d:a.joined, ref:'OPENING', t:'Opening balance brought forward', dr:a.opening, cr:0 }, ...bks.filter(b => b.postedOn).map(b => ({ d:b.postedOn, ref:b.ref, t:`Invoice · ${b.service}`, dr:b.price, cr:0 })), ...pays.map(p => ({ d:p.date, ref:p.ref, t:`Payment · ${p.method}`, dr:0, cr:p.status === 'Posted' ? p.amount : 0 }))].sort((x, y) => x.d < y.d ? -1 : 1); rows.forEach((r, i) => { if (i) run += r.dr - r.cr; r.bal = run; });
    body = card(tab === 'statements' ? 'Statement of account' : 'Transactions', `<div class="tw"><table class="tbl"><thead><tr><th>Date</th><th>Reference</th><th>Description</th><th class="r">Debit</th><th class="r">Credit</th><th class="r">Balance</th></tr></thead><tbody>${rows.map(r => `<tr><td>${fd(r.d)}</td><td class="mono">${r.ref}</td><td>${r.t}</td><td class="r">${r.dr ? num(r.dr) : ''}</td><td class="r">${r.cr ? num(r.cr) : ''}</td><td class="r">${num(r.bal)}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="5">Balance due</td><td class="r">${pk(run)}</td></tr></tfoot></table></div>`, { np:true }); }
  if (tab === 'commissions') body = card('', `<div class="tw"><table class="tbl"><thead><tr><th>Reference</th><th>Booking</th><th>Basis</th><th class="r">Amount</th><th>Status</th></tr></thead><tbody>${com.map(c => `<tr><td class="mono">${c.ref}</td><td class="mono">${bk(c.bookingId)?.ref}</td><td>${c.basis}</td><td class="r">${pk(c.amount)}</td><td>${pill(c.status)}</td></tr>`).join('') || '<tr><td colspan="5" class="mut">No commission records.</td></tr>'}</tbody></table></div>`, { np:true });
  if (tab === 'activity') body = card('Activity', `<ul class="tl">${S.audit.filter(x => x.ref === a.code || x.next.includes(a.name)).map(x => `<li><span class="td"></span><div><div class="tt">${esc(x.action)} · ${esc(x.next)}</div><div class="tm">${fdt(x.at)} · ${esc(x.user)}</div></div></li>`).join('') || '<li class="mut">No recent activity.</li>'}</ul>`);
  return `<button class="back" data-a="go" data-r="subagents">${ic('arrow-left')}All sub-agents</button>
  <div class="card"><div class="prof"><span class="pav">${initials(a.name)}</span><div><h2>${esc(a.name)} ${pill(a.status)}</h2><div class="meta"><span class="mono">${a.code}</span><span>${ic('map-pin')}${esc(a.city)}</span><span>${ic('phone')}${esc(a.contact)}</span></div></div><div class="acts">${a.status === 'Active' ? btn('Log request', 'newAgentReq', { icon:'inbox', data:`data-id="${id}"`, perm:'agent.create' }) + btn('Suspend', 'agentApprove', { icon:'pause', data:`data-id="${id}"`, perm:'agent.approve' }) : ''}${a.status !== 'Active' ? btn(a.status === 'Suspended' ? 'Reactivate' : 'Approve agent', 'agentApprove', { cls:'btn-p', icon:'check', data:`data-id="${id}"`, perm:'agent.approve' }) : btn('Record payment', 'agentDeposit', { cls:'btn-p', icon:'hand-coins', data:`data-id="${id}"`, perm:'payment.create' })}</div></div></div>
  <div class="mt">${tabs('subagent', [['overview', 'Overview'], ['bookings', 'Bookings', bks.length], ['transactions', 'Transactions'], ['commissions', 'Commissions', com.length], ['statements', 'Statements'], ['activity', 'Activity']])}${body}</div>`;
};

