  const tog = (path, label, sub, v) => `<div class="srow"><div><b>${label}</b><small>${sub}</small></div><label class="sw"><input type="checkbox" data-set="${path}" aria-label="${label}" ${v ? 'checked' : ''} ${ed ? '' : 'disabled'}><i></i></label></div>`;
